// Golden values reproduced from the prototype's own logic (design lines 3096–5239 run in node:vm, renderValsEN:
// src/features/pid/pid.golden.json, generated by scripts/proto-golden-pid.ts) on the prototype's PID, PID_TAGS,
// PID_STEPS, PARTS (HLT usage = the Harbor Line BOM) and the Harbor Line activities — the rows the P&ID tables are
// seeded from. Covers the derived status, the register cells, chips, scope segment, filters and searches, KPIs,
// coverage and nav badge, the validation steps, the overlay table, every tag drawer (record, candidates, actions) and
// the mapping overrides (`pidOv`: map, unlink, all linked).
import { describe, expect, it } from 'vitest';
import GOLD from '@/features/pid/pid.golden.json';
import { bomScope, partStatus, partType, pidTagKind, stepState, type PartStatus, type PartType, type PlcType } from '@/server/db/codes';
import PROTO from '@/server/prototype/prototype-data.json';
import GEN from '@/server/prototype/prototype-generated.json';
import {
  PID_SCOPE_SEG, activityText, candidateTag, extractedStepLabel, feedbackMissing, feedbackView, filterPidTags, kindLabel, nextRevision, overlayTags, partLine,
  pidChips, pidCoverage, pidKpis, pidNavBadge, pidScopeFilterOf, pidScopeTag, pidStatusFilterOf, pidStatusTag, pidStepView, pidTagActions,
  pidTagRecord, pidTagStatusOf, plcView, refText, releasedStepLabel, scopeLabel, searchPidCandidates, statusLabel, type PidTagLike,
} from './pid';

/* eslint-disable @typescript-eslint/no-explicit-any */
const G = (GOLD as any).en;
const P = PROTO as any;
const PARTS = (P.PARTS as { ref: string; name: string; type: string; status: string; usage: Record<string, number> }[]).map((p) => ({
  ref: p.ref, name: p.name, type: partType.code(p.type) as PartType, status: partStatus.code(p.status) as PartStatus, usage: p.usage,
}));
const PART = new Map(PARTS.map((p) => [p.ref, p]));
const BOM = new Set(PARTS.filter((p) => (p.usage.HLT ?? 0) > 0).map((p) => p.ref));
const ACT = new Map(((GEN as any).projectData['HLT-026'].ACTS as { id?: string; n: string }[]).filter((a) => a.id).map((a) => [a.id!, a.n]));

/** The prototype's PID_TAGS as the data layer reads them, with an optional mapping override (`pidOv`). */
function tags(ov: Record<string, string> = {}): PidTagLike[] {
  return (P.PID_TAGS as any[]).map((t, i) => {
    const ref = (t.tag in ov ? ov[t.tag] : t.ref) || null;
    const part = ref ? PART.get(ref) : undefined;
    const scope = bomScope.code(t.scope);
    return {
      tag: t.tag, description: t.desc, kind: pidTagKind.code(t.kind), scope, partRef: ref, partName: part?.name ?? null, partStatus: part?.status ?? null, note: t.note,
      activityCode: t.act, activityName: ACT.get(t.act) ?? null, plcType: (t.plc || null) as PlcType | null, stateFeedback: t.fb, role: t.role,
      status: pidTagStatusOf(scope, ref, part, !!ref && BOM.has(ref)), sheet: 1 + (i % 4),
    };
  });
}
const SHEET = { documentNumber: P.PID.doc, revision: P.PID.rev, sheetCount: P.PID.sheets, statusLabel: P.PID.status, issuedOn: '2026-09-12' };

const LO = 'var(--color-accent-300)';
const OK = 'var(--color-text)';
const kpiRows = (ts: PidTagLike[]) => {
  const c = pidCoverage(ts);
  const subs = [`${SHEET.sheetCount} sheets · ${SHEET.statusLabel} · ${P.PID.date}`, `${c.overlay} overlay · ${c.client} client-supplied`, `${c.linked} / ${c.inScope} tags`, 'Blocks release for construction', 'Not in BOM · outdated · not validated'];
  return pidKpis(SHEET, c).map((k, i) => ({ label: k.label, value: k.value, sub: subs[i], color: k.lo ? LO : OK }));
};
const row = (t: PidTagLike, selected: string | null = null) => {
  const plc = plcView(t.plcType);
  const fb = feedbackView(t);
  return {
    tag: t.tag, desc: t.description, kind: kindLabel(t.kind), scope: scopeLabel(t.scope), scopeClass: pidScopeTag(t.scope), ref: t.partRef ?? '', refText: refText(t), partName: partLine(t),
    status: statusLabel(t.status), tagClass: pidStatusTag(t.status), actText: activityText(t.activityCode, t.activityName), plcText: plc.text, plcTag: plc.asTag, plcPlain: !plc.asTag,
    plcClass: plc.tagClass, fbWarn: feedbackMissing(t), fbText: fb.text, fbColor: fb.tone === 'warn' ? LO : fb.tone === 'text' ? OK : 'var(--color-neutral-500)',
    tagColor: selected === t.tag ? LO : OK, hasPart: pidTagActions(t).hasPart,
  };
};
const chipRows = (ts: PidTagLike[], active: string | null = null) =>
  pidChips(ts).map((c) => {
    const on = (c.value ? statusLabel(c.value) : null) === active;
    return { label: c.label, count: String(c.count), bg: on ? 'var(--color-accent-900)' : 'transparent', border: on ? 'var(--color-accent-700)' : 'var(--color-neutral-800)', color: on ? 'var(--color-accent-200)' : 'var(--color-neutral-300)' };
  });
const statusCode = (label: string) => pidStatusFilterOf(['linked', 'unmapped', 'unknown_ref', 'not_in_bom', 'part_not_validated', 'part_outdated', 'part_obsolete', 'client'].find((s) => statusLabel(s as never) === label));
const drawer = (t: PidTagLike) => {
  const a = pidTagActions(t);
  return {
    tag: t.tag, desc: t.description, kind: kindLabel(t.kind), scope: scopeLabel(t.scope), scopeClass: pidScopeTag(t.scope), status: statusLabel(t.status), tagClass: pidStatusTag(t.status),
    isClient: a.isClient, fbWarn: feedbackMissing(t), canMap: a.canMap, hasPart: a.hasPart, notInBom: a.notInBom,
    // The prototype hard-codes "PID-HLT-026" in the sheet label; the rebuild uses the sheet's own document number (the same here).
    meta: pidTagRecord(t, SHEET.documentNumber),
    // E-6 (R-108): the whole catalogue is searched, the project BOM's articles first; the prototype's 8 candidates (BOM
    // articles of a compatible type, catalogue order) are the first BOM-marked results of the default search.
    candidates: searchPidCandidates(PARTS, { kind: t.kind, q: '', type: 'compatible', bomRefs: BOM }).rows.filter((p) => p.inBom).slice(0, 8)
      .map((p) => ({ ref: p.ref, name: p.name, status: partStatus.label(p.status), tagClass: candidateTag(p.status) })),
  };
};

describe('P&ID register (pidRows, pidList, pidChips, pidScopeSeg — 4766–4772)', () => {
  it('derived status and every register cell of the 24 tags', () => {
    expect(tags().map((t) => row(t))).toEqual(G.rows);
    expect(tags().map((t) => row(t, 'XV-111').tagColor)).toEqual(G.selectedTagColor);
  });

  it('status chips (only the statuses present, with counts) and the scope segment', () => {
    expect(chipRows(tags())).toEqual(G.chips);
    expect(PID_SCOPE_SEG.map((o) => o.label)).toEqual(G.scopeSeg.map((o: any) => o.label));
    for (const [label, f] of Object.entries(G.filters as Record<string, { tags: string[]; chips: unknown[] }>)) {
      const status = statusCode(label);
      expect(filterPidTags(tags(), { status, scope: null, q: '' }).map((t) => t.tag), label).toEqual(f.tags);
      expect(chipRows(tags(), label), label).toEqual(f.chips);
    }
  });

  it('scope filter, searches (tag + description + reference + PLC + feedback) and combinations', () => {
    for (const [label, f] of Object.entries(G.scopes as Record<string, { tags: string[] }>)) {
      expect(filterPidTags(tags(), { status: null, scope: pidScopeFilterOf(bomScope.code(label)), q: '' }).map((t) => t.tag), label).toEqual(f.tags);
    }
    for (const [q, ids] of Object.entries(G.searches as Record<string, string[]>)) expect(filterPidTags(tags(), { status: null, scope: null, q }).map((t) => t.tag), q).toEqual(ids);
    expect(filterPidTags(tags(), { status: 'unmapped', scope: 'overlay', q: '' }).map((t) => t.tag)).toEqual(G.combos['Unmapped|Overlay']);
    expect(filterPidTags(tags(), { status: 'linked', scope: 'keystone', q: 'vfd' }).map((t) => t.tag)).toEqual(G.combos['Linked|Keystone|vfd']);
    expect(filterPidTags(tags(), { status: 'client', scope: 'keystone', q: '' }).map((t) => t.tag)).toEqual(G.combos['Client|Keystone']);
    expect(filterPidTags(tags(), { status: 'part_outdated', scope: null, q: 'zzz' })).toEqual([]);
    expect(G.combos['Part outdated|zzz']).toEqual({ tags: [], noPid: true });
    // The displayed (translated) text is searched too.
    expect(filterPidTags(tags(), { status: null, scope: null, q: 'manquant' }, (t) => (feedbackView(t).text === 'Missing' ? 'Manquant' : '')).map((t) => t.tag)).toEqual(['XV-111']);
    expect([pidStatusFilterOf('part_outdated'), pidStatusFilterOf('Part outdated'), pidScopeFilterOf('overlay'), pidScopeFilterOf('Overlay')]).toEqual(['part_outdated', null, 'overlay', null]);
  });

  it('overlay table: Overlay and Client tags in tag order', () => {
    expect(overlayTags(tags()).map((t) => ({ tag: t.tag, desc: t.description, scope: scopeLabel(t.scope), scopeClass: pidScopeTag(t.scope), refText: refText(t), status: statusLabel(t.status), tagClass: pidStatusTag(t.status) })))
      .toEqual(G.overlay);
  });
});

describe('P&ID KPIs, coverage, badge and validation steps (pidKpis 4776, pidSteps 4777, navEng 5150)', () => {
  it('KPI tiles (59 %, 6 unmapped, 3 reference issues) and the nav badge 9', () => {
    expect(kpiRows(tags())).toEqual(G.kpis);
    expect(pidCoverage(tags())).toEqual({ inScope: 22, linked: 13, pct: 59, unmapped: 6, referenceIssues: 3, overlay: 5, client: 2 });
    expect(String(pidNavBadge(pidCoverage(tags())))).toBe(G.navBadge);
  });

  it('validation steps', () => {
    const steps = (P.PID_STEPS as [string, 'done' | 'doing' | 'todo', string, string][]).map(([label, st, date, who]) => {
      const v = pidStepView(st);
      return { label, who, date, dot: v.dot, color: v.color, state: v.label, tagClass: v.tagClass };
    });
    expect(steps).toEqual(G.steps);
    expect(stepState.codes.map((s) => pidStepView(s).label)).toEqual(['Done', 'In progress', 'To do']);
    expect([extractedStepLabel('C'), releasedStepLabel('C')]).toEqual([G.steps[0].label, G.steps[4].label]);
    expect(['C', 'Y', 'Z', '02', '9', 'C1'].map(nextRevision)).toEqual(['D', 'Z', 'Z1', '03', '10', 'C1+']);
  });

  it('a project without tags in our scope: 0 %, no badge "0"', () => {
    const c = pidCoverage([]);
    expect([c.pct, pidNavBadge(c)]).toEqual([0, null]);
    const clientOnly = pidCoverage(tags().filter((t) => t.scope === 'client'));
    expect([clientOnly.inScope, pidNavBadge(clientOnly)]).toEqual([0, null]);
  });
});

describe('P&ID tag drawer (pidTagVals 4781, pidCands 4780)', () => {
  it('record, candidates and actions of every tag', () => {
    for (const t of tags()) expect(drawer(t), t.tag).toEqual(G.drawers[t.tag]);
  });

  it('mapping overrides: map a candidate, unlink, map a non-validated part, everything linked', () => {
    const scenario = (ov: Record<string, string>, tag?: string) => {
      const ts = tags(ov);
      return {
        kpis: kpiRows(ts),
        chips: chipRows(ts),
        rows: ts.map((t) => ({ tag: t.tag, refText: refText(t), partName: partLine(t), status: statusLabel(t.status), tagClass: pidStatusTag(t.status), hasPart: pidTagActions(t).hasPart })),
        navBadge: pidNavBadge(pidCoverage(ts)) == null ? '' : String(pidNavBadge(pidCoverage(ts))),
        drawer: tag ? drawer(ts.find((x) => x.tag === tag)!) : null,
      };
    };
    expect(scenario({ 'TT-102': 'EL-SWG-11KV' }, 'TT-102')).toEqual(G.overrides.mapTT102);
    expect(scenario({ 'LT-101': '' }, 'LT-101')).toEqual(G.overrides.unlinkLT101);
    expect(scenario({ 'XV-111': 'CTL-WIND-SN' }, 'XV-111')).toEqual(G.overrides.mapNotValidated);
    expect(scenario(G.overrides.allLinkedMap)).toEqual(G.overrides.allLinked);
    expect(G.overrides.allLinked.navBadge).toBe('');
  });

  it('fixes: Unknown ref has a chip and can be unlinked; Not in BOM offers "Add reference to project BOM"', () => {
    const ts = tags({ 'TT-102': 'XX-NOT-IN-CAT', 'FT-110': 'KS-STL-0450', 'ZS-310': PARTS.find((p) => !BOM.has(p.ref) && p.status === 'validated')!.ref });
    const unknown = ts.find((t) => t.tag === 'TT-102')!;
    expect([unknown.status, pidStatusTag(unknown.status), pidTagActions(unknown)]).toEqual(['unknown_ref', 'tag tag-accent', { canMap: true, isClient: false, hasPart: false, canUnlink: true, notInBom: false }]);
    expect(pidChips(ts).map((c) => c.label)).toEqual(['All', 'Linked', 'Unmapped', 'Unknown ref', 'Not in BOM', 'Part not validated', 'Part outdated', 'Client']);
    const notInBom = ts.find((t) => t.tag === 'ZS-310')!;
    expect([notInBom.status, pidStatusTag(notInBom.status), pidTagActions(notInBom).notInBom, pidTagActions(notInBom).hasPart]).toEqual(['not_in_bom', 'tag tag-outline', true, true]);
    // KS-STL-0450 is in the Harbor Line BOM: a structural part linked to an instrument (no type check on a stored mapping).
    expect(ts.find((t) => t.tag === 'FT-110')!.status).toBe('linked');
    expect(pidCoverage(ts).referenceIssues).toBe(5);
    expect(pidTagActions(ts.find((t) => t.tag === 'T-101')!)).toEqual({ canMap: false, isClient: true, hasPart: false, canUnlink: false, notInBom: false });
  });
});
